package org.diy.liferecorder;
import android.os.*;import android.content.*;import android.media.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
/** Editable audio selection, named enrollment and explicitly selected speaker-label merging. */
public final class VoiceSegmentActivity extends AppScreen {
 private JSONObject source,chosen;private final ArrayList<JSONObject> candidates=new ArrayList<>();private final Map<String,JSONObject> sources=new LinkedHashMap<>();private final Map<String,CheckBox> checks=new LinkedHashMap<>();private final Set<String> selectedKeys=new HashSet<>();private EditText name;private Spinner target;private Switch permanent;private TextView range,count;private SeekBar from,to;private long start,end;private boolean adjusting,busy;private MediaPlayer player;private final Handler playback=new Handler();private JSONArray profiles;
 public void onCreate(Bundle state){super.onCreate(state);frame("声纹校准与命名");button(body,"‹ 返回",this::finish);body.addView(title("声纹校准与命名",24));body.addView(text("选择清晰发言，命名并校准说话人",13,MUTED));background(()->{
   source=store.audio(getIntent().getStringExtra("id"));int index=getIntent().getIntExtra("segment_index",-1);JSONArray segments=AudioReview.object(source.optString("speech_json")).optJSONArray("segments");if(segments==null||index<0||index>=segments.length())throw new IOException("语句已变化，请返回刷新");chosen=new JSONObject(segments.getJSONObject(index).toString()).put("segment_index",index).put("source_id",source.getString("id"));
   JSONArray ids=AudioReview.object(getIntent().getStringExtra("selection")).optJSONArray("sources");if(ids==null)ids=new JSONArray().put(source.getString("id"));if(ids.length()>1000)throw new IOException("来源过多，请缩小选择范围");
   for(int i=0;i<ids.length();i++){JSONObject record=store.audio(ids.getString(i));sources.put(record.getString("id"),record);JSONArray units=TranscriptDocument.units(record);for(int n=0;n<units.length();n++)if(units.getJSONObject(n).has("segment_index"))candidates.add(units.getJSONObject(n));}sources.put(source.getString("id"),source);profiles=VoiceProfiles.read(new OfflinePacks(this));
  },this::renderSelection);
 }
 private void renderSelection(){notice.setText("");
  selectedKeys.add(key(chosen));LinearLayout info=card(body);info.addView(text("原音来源 · "+new java.text.SimpleDateFormat("M/d HH:mm",Locale.CHINA).format(new Date(source.optLong("created"))),12,SAGE));info.addView(rawText(source.optString("title"),14,INK));info.addView(text("请回听并调整范围，选取只有一人说话的清晰声音。所选发言会统一标注为你确认的说话人。",12,MUTED));
  LinearLayout profile=card(body);profile.addView(title("声纹登记建档",20));profile.addView(rawTitle(chosen.optString("speaker","未命名"),17));range=text("",13,SAGE);profile.addView(range);start=Math.max(0,chosen.optLong("start_ms"));end=Math.min(source.optLong("duration"),Math.max(start+1,chosen.optLong("end_ms")));if(end-start>30000)end=start+30000;
  WaveformView wave=new WaveformView(this,f->{});profile.addView(wave,new LinearLayout.LayoutParams(-1,dp(65)));wave.post(()->{if(!source.optString("path").isEmpty())wave.load(new File(source.optString("path")));});profile.addView(text("调整样本起止位置（秒）",12,MUTED));from=new SeekBar(this);to=new SeekBar(this);int limit=(int)Math.min(Integer.MAX_VALUE/1000,Math.max(1,source.optLong("duration")/100));from.setMax(limit);to.setMax(limit);from.setProgress((int)(start/100));to.setProgress((int)(end/100));profile.addView(from);profile.addView(to);SeekBar.OnSeekBarChangeListener listener=new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int value,boolean user){if(!user||adjusting||busy)return;adjusting=true;long duration=source.optLong("duration");if(bar==from){start=Math.min(value*100L,Math.max(0,duration-100));if(end<=start)end=Math.min(duration,start+3000);if(end-start>40000)end=start+40000;}else{end=Math.max(100,Math.min(duration,value*100L));if(start>=end)start=Math.max(0,end-3000);if(end-start>40000)start=end-40000;}from.setProgress((int)(start/100));to.setProgress((int)(end/100));adjusting=false;stopPreview();updateRange();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}};from.setOnSeekBarChangeListener(listener);to.setOnSeekBarChangeListener(listener);updateRange();button(profile,"▷ 试听所选声音",this::preview);
  name=field(profile,"说话人姓名或称呼",chosen.optBoolean("speaker_confirmed")?chosen.optString("speaker"):"",android.text.InputType.TYPE_CLASS_TEXT);profile.addView(text("合并归属于",12,MUTED));target=new Spinner(this);ArrayList<String> labels=new ArrayList<>();labels.add("新建说话人／仅标注名称");for(int i=0;i<profiles.length();i++)labels.add(profiles.optJSONObject(i).optString("name"));target.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels));profile.addView(target);target.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int pos,long id){name.setEnabled(pos==0);if(pos>0)name.setText(profiles.optJSONObject(pos-1).optString("name"));}public void onNothingSelected(android.widget.AdapterView<?> p){}});
  permanent=new Switch(this);permanent.setText("保存为长期声纹 · 本机候选匹配");permanent.setThumbTintList(android.content.res.ColorStateList.valueOf(android.graphics.Color.WHITE));permanent.setTrackTintList(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{SAGE,0xffe9e3d8}));permanent.setChecked(true);profile.addView(permanent);profile.addView(text("关闭后仅统一标注所选发言；开启后使用上方选中的单人声音作为样本。",12,MUTED));
  LinearLayout merge=card(body);merge.addView(title("多段发言合并为同一人",19));merge.addView(text("勾选你已回听确认属于同一人的发言。匿名编号仅限各自录音，不自动跨文件合并。",12,MUTED));count=text("",12,SAGE);merge.addView(count);button(merge,"选择／取消本文件的同名发言",()->{boolean all=true;for(JSONObject u:candidates)if(sameLabel(u)&&!selectedKeys.contains(key(u)))all=false;for(JSONObject u:candidates)if(sameLabel(u)){if(all)selectedKeys.remove(key(u));else selectedKeys.add(key(u));if(checks.containsKey(key(u)))checks.get(key(u)).setChecked(!all);}updateCount();});LinearLayout list=column();merge.addView(list);appendCandidates(list,0);updateCount();primary(body,"保存校准与命名",this::save);button(body,"管理已登记的声纹与来源样本",()->startActivity(new Intent(this,OfflineActivity.class).putExtra("section","voice")));body.addView(text("声纹特征仅在本机提取计算。",12,SAGE));
 }
 private boolean sameLabel(JSONObject u){return u.optString("source_id").equals(source.optString("id"))&&u.optString("speaker").equals(chosen.optString("speaker"));}
 private String key(JSONObject u){return u.optString("source_id")+":"+u.optInt("segment_index");}
 private void appendCandidates(LinearLayout list,int fromIndex){int endIndex=Math.min(candidates.size(),fromIndex+25);for(int i=fromIndex;i<endIndex;i++){JSONObject unit=candidates.get(i),record=sources.get(unit.optString("source_id"));CheckBox check=new CheckBox(this);check.setText(unit.optString("speaker")+" · "+TranscriptDocument.clock(record.optLong("created")+unit.optLong("start_ms"))+"\n"+unit.optString("text"));check.setTextSize(13);check.setTextColor(INK);check.setMinHeight(dp(54));check.setMaxLines(3);check.setEllipsize(android.text.TextUtils.TruncateAt.END);check.setChecked(selectedKeys.contains(key(unit)));checks.put(key(unit),check);check.setOnCheckedChangeListener((b,value)->{if(value)selectedKeys.add(key(unit));else selectedKeys.remove(key(unit));updateCount();});list.addView(check);}if(endIndex<candidates.size()){Button more=button(list,"展开更多候选发言",()->{});more.setOnClickListener(v->{list.removeView(more);appendCandidates(list,endIndex);});}}
 private void updateRange(){range.setText(String.format(Locale.CHINA,"样本 %s – %s · %.1f 秒",TranscriptDocument.clock(source.optLong("created")+start),TranscriptDocument.clock(source.optLong("created")+end),(end-start)/1000.0));}
 private void updateCount(){int n=selectedKeys.size();if(count!=null)count.setText("已选择 "+n+" 段发言");}
 private JSONObject sample()throws Exception{JSONObject selected=new JSONObject(chosen.toString()).put("start_ms",start).put("end_ms",end);if(source.optInt("source_retained",1)==0){JSONArray ranges=new JSONObject(source.optString("vad_map")).getJSONArray("ranges");long a=-1,b=-1;for(int i=0;i<ranges.length();i++){JSONObject r=ranges.getJSONObject(i);long x=r.getLong("source_start_sample")/16,y=r.getLong("source_end_sample")/16;if(start>=x&&start<y)a=r.getLong("output_start_sample")/16+start-x;if(end>x&&end<=y)b=r.getLong("output_start_sample")/16+end-x;}if(a<0||b<=a)throw new IOException("选择范围包含未保留的音频，请调整样本范围");selected.put("asset_start_ms",a).put("asset_end_ms",b);}return selected;}
 private void preview(){stopPreview();try{JSONObject sample=sample();long at=sample.optLong("asset_start_ms",start),until=sample.optLong("asset_end_ms",end);player=new MediaPlayer();player.setDataSource(source.getString("path"));player.setOnPreparedListener(p->{p.setOnSeekCompleteListener(ready->{if(ready!=player)return;ready.start();playback.post(new Runnable(){public void run(){if(player==null)return;try{if(player.getCurrentPosition()>=until){stopPreview();return;}}catch(Exception ignored){stopPreview();return;}playback.postDelayed(this,60);}});});p.seekTo((int)at);});player.setOnErrorListener((p,w,e)->{stopPreview();notice.setText("样本音频暂不可用");return true;});player.prepareAsync();}catch(Exception e){notice.setText(e.getMessage());}}
 private void save(){if(busy)return;try{final String label=name.getText().toString().trim();if(label.isEmpty()||label.length()>60)throw new IOException("请输入 1–60 字的说话人名称");final boolean enroll=permanent.isChecked();final JSONObject selectedSample=sample();if(enroll&&(end-start<2400||end-start>40000))throw new IOException("请选择 3–40 秒清晰单人声音");final ArrayList<JSONObject> selected=new ArrayList<>();for(JSONObject unit:candidates)if(selectedKeys.contains(key(unit)))selected.add(unit);if(selected.isEmpty())throw new IOException("请勾选至少一段需要标注的发言");final String existing=target.getSelectedItemPosition()>0?profiles.getJSONObject(target.getSelectedItemPosition()-1).getString("id"):"";new LocalDialog(this).setTitle("确认所选声音和人物").setMessage("将 "+selected.size()+" 段发言标注为“"+label+"”。"+(enroll?"请确认试听样本只有这位说话人，声纹仅保存在本机。":"本次仅保存人物标注。")) .setPositiveButton("保存",(d,w)->{busy=true;stopPreview();background(()->{OfflinePacks packs=new OfflinePacks(this);String profile=existing;boolean created=false;String sampleId="";try{verifySources(selected);if(enroll){if(!packs.ready("speaker"))throw new IOException("请先在声纹管理中下载并验证识别包");String expected=source.optInt("source_retained",1)==0?source.optString("retained_sha"):source.optString("sha");if(!org.diy.lifecore.LocalSecurity.hash(new File(source.getString("path"))).equals(expected))throw new IOException("音频校验失败");if(profile.isEmpty()){profile=VoiceProfiles.create(packs,label);created=true;}sampleId=OfflineSpeech.supplement(packs,source,selectedSample,profile);}store.getWritableDatabase().beginTransaction();try{verifySources(selected);applyLabels(selected,profile,label);store.getWritableDatabase().setTransactionSuccessful();}finally{store.getWritableDatabase().endTransaction();}}catch(Exception error){if(created)VoiceProfiles.remove(packs,profile,null);else if(!sampleId.isEmpty())VoiceProfiles.remove(packs,profile,sampleId);busy=false;throw error;}},()->{busy=false;notice.setText("已保存人物标注与声纹设置");setResult(RESULT_OK);finish();});}).setNegativeButton("取消",null).show();}catch(Exception e){notice.setText(e.getMessage());}}
 private void verifySources(List<JSONObject> selected)throws Exception{Set<String> ids=new HashSet<>();ids.add(source.getString("id"));for(JSONObject unit:selected)ids.add(unit.getString("source_id"));for(String id:ids){JSONObject old=sources.get(id),current=store.audio(id);if(old==null||old.optLong("transcript_revision")!=current.optLong("transcript_revision")||!old.optString("path").equals(current.optString("path")))throw new IOException("来源已变化，请返回刷新后再设置");}}
 private void applyLabels(List<JSONObject> selected,String profile,String label)throws Exception{Map<String,JSONObject> updates=new LinkedHashMap<>();for(JSONObject u:selected){String id=u.getString("source_id");JSONObject speech=updates.get(id);if(speech==null){speech=new JSONObject(sources.get(id).getString("speech_json"));updates.put(id,speech);}JSONObject segment=speech.getJSONArray("segments").getJSONObject(u.getInt("segment_index"));segment.put("speaker",label).put("speaker_confirmed",true);if(profile.isEmpty())segment.remove("voice_profile_id");else segment.put("voice_profile_id",profile);}for(String id:updates.keySet())store.editSpeech(id,sources.get(id).optLong("transcript_revision"),updates.get(id));}
 private void stopPreview(){playback.removeCallbacksAndMessages(null);if(player!=null){player.release();player=null;}}
 protected void onPause(){stopPreview();super.onPause();}public void onDestroy(){stopPreview();super.onDestroy();}
}
